    /** @return array<string, array<int, string>> */
    public function rules(): array
    {
        return [
            'title' => ['required', 'string', 'max:120'],
            'price_cents' => ['required', 'integer', 'min:0'],
            'tags' => ['array'],
            'tags.*' => ['string'],
        ];
    }
}

// OfferController (use App\Http\Requests\StoreOfferRequest; drop the Request and JsonResponse imports if unused)
public function store(StoreOfferRequest $request, TagNormaliser $normaliser): OfferResource
{
    $offer = Offer::create([
        ...$request->safe()->except('tags'),
        'tags' => $normaliser->unique($request->validated('tags', [])),
    ]);

    return new OfferResource($offer);
}

